// Parity of src/engine/gacha.ts with the LEGACY Python gacha (backend/gacha_service.py, backend/banner_rotation.py and the
// pure part of server/gacha_transaction.py).
//
// GOLDEN below was generated by running the LEGACY modules (reconstructed verbatim from the Google Drive archive, files
// 1jRUZUQy7imD1wjNUE9PkqOLPVZ9GYTER and 1lOxEbY2IwxPDr9aL8I7_uRmIMLro5GcA; the reconstruction passes all 45 cases of the
// LEGACY tests/test_gacha_service.py, test_gacha_edge_cases.py and test_banner_rotation.py) under CPython 3.11 against
// the repository's game/data/content packs. The reference draws from `random.Random(seed)`, the port from CpythonRandom:
// equal seeds must give equal pulls, probabilities (bit for bit), pity states and error messages.
//
// The 180,600-line fingerprint covers 15 banner configurations x 40 seeds x 300 chained pulls (every field of every
// pull, probabilities as IEEE-754 bits, the full pity state, and the next random() after each chain).
//
// Known, accepted divergence: the reference rejects a float-typed counter such as `weapon_fate_knots: 1.0`; JSON numbers
// in JS cannot tell 1.0 from 1, so the port accepts it (that case is left out of GOLDEN.errors).
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { GachaError, GachaRules, pityState, pityStatePayload, type AccountPityState, type PullResult } from "../../src/engine/gacha";
import { isoUtc, parseEpoch, RotationError } from "../../src/engine/gacha-rotation";
import { CpythonRandom } from "../../src/engine/random";

const CONTENT = join(import.meta.dirname, "..", "..", "..", "game", "data", "content");
const pack = (name: string): unknown => JSON.parse(readFileSync(join(CONTENT, name), "utf8"));
const rules = new GachaRules(pack("economy_part1.json"), pack("characters_part1.json"), pack("weapons_part1.json"));
const EPOCH = new Date("2026-10-05T00:00:00Z");

type Any = any; // eslint-disable-line @typescript-eslint/no-explicit-any

function bits(value: number): string {
  const view = new DataView(new ArrayBuffer(8));
  view.setFloat64(0, value);
  return [...new Uint8Array(view.buffer)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

const flag = (value: boolean | null): string => (value === null ? "N" : value ? "T" : "F");

function stateJson(state: AccountPityState): string {
  const payload = pityStatePayload(state) as unknown as Record<string, unknown>;
  return JSON.stringify(Object.fromEntries(Object.keys(payload).sort().map((key) => [key, payload[key]])));
}

function line(result: PullResult): string {
  return [
    result.banner_id,
    result.banner_type,
    String(result.rarity),
    result.reward_id ?? "-",
    result.outcome_pool_id ?? "-",
    flag(result.is_featured),
    flag(result.hard_pity_triggered),
    flag(result.featured_guarantee_triggered),
    flag(result.target_guarantee_triggered),
    flag(result.minimum_four_star_triggered),
    result.rarity_probabilities.map(([, probability]) => bits(probability)).join(","),
    stateJson(result.account_state),
  ].join("|");
}

const row = (result: PullResult): unknown[] => [
  result.rarity,
  result.reward_id,
  result.outcome_pool_id,
  result.is_featured,
  result.hard_pity_triggered,
  result.featured_guarantee_triggered,
  result.target_guarantee_triggered,
  result.minimum_four_star_triggered,
  result.rarity_probabilities.map(([, probability]) => probability),
];

function failure(action: () => unknown): [string, string] | null {
  try {
    action();
  } catch (error) {
    if (error instanceof GachaError) return [error.kind, error.message];
    if (error instanceof RotationError) return [error.kind, error.message];
    throw error;
  }
  return null;
}

describe("gacha parity with the LEGACY reference (GOLDEN)", () => {
  it("180,600 chained pulls match the reference fingerprint", () => {
    const lines: string[] = [];
    const counts: Record<string, number[]> = {};
    for (const [bannerId, overrides] of GOLDEN.configs as [string, Partial<AccountPityState>][]) {
      const key = `${bannerId}|${overrides.selected_weapon_target_id ?? overrides.selected_character_id ?? ""}`;
      const tally = { 3: 0, 4: 0, 5: 0 };
      for (let seed = 0; seed < GOLDEN.fingerprint.seeds; seed++) {
        const rng = new CpythonRandom(BigInt(seed));
        let state = pityState(overrides);
        for (let index = 0; index < GOLDEN.fingerprint.chain; index++) {
          const result = rules.pull(state, bannerId, rng);
          lines.push(line(result));
          tally[result.rarity] += 1;
          state = result.account_state;
        }
        lines.push(`end|${seed}|${bits(rng.random())}`);
      }
      counts[key] = [tally[5], tally[4], tally[3]];
    }
    expect(counts).toEqual(GOLDEN.fingerprint.counts);
    expect(lines.length).toBe(GOLDEN.fingerprint.lines);
    expect(createHash("sha256").update(lines.join("\n"), "utf8").digest("hex")).toBe(GOLDEN.fingerprint.sha256);
  }, 60_000);

  it("detailed 10-pull chains: every field and probability", () => {
    for (const entry of GOLDEN.detailed as Any[]) {
      const rng = new CpythonRandom(BigInt(entry.seed));
      let state = pityState(entry.start);
      const rows: unknown[] = [];
      for (let index = 0; index < 10; index++) {
        const result = rules.pull(state, entry.banner_id, rng);
        rows.push(row(result));
        state = result.account_state;
      }
      expect(rows, `${entry.banner_id} seed=${entry.seed}`).toEqual(entry.rows);
      expect(pityStatePayload(state)).toEqual(entry.final);
    }
  });

  it("describe_next_pull and the raw rarity roll", () => {
    for (const entry of GOLDEN.describe as Any[]) {
      const state = pityState(entry.state);
      expect(rules.describeNextPull(state, entry.banner_id), entry.banner_id).toEqual(entry.odds);
      const raw = rules.getRarityProbabilities(state, entry.banner_id);
      expect([raw[5], raw[4], raw[3]]).toEqual(entry.raw);
    }
  });

  it("the 5★ curve of every banner type, bit for bit", () => {
    const curve = (bannerId: string, field: keyof AccountPityState, length: number, star: 3 | 4 | 5) =>
      Array.from({ length }, (_, pity) => rules.getRarityProbabilities(pityState({ [field]: pity }), bannerId)[star]);
    expect(curve("character:oath_01_aveline", "character_five_star_pity", 80, 5)).toEqual(GOLDEN.curve.character);
    expect(curve("weapon:oath_01_aveline", "weapon_five_star_pity", 65, 5)).toEqual(GOLDEN.curve.weapon);
    expect(curve("hall_of_ancestors", "standard_five_star_pity", 80, 5)).toEqual(GOLDEN.curve.standard);
    expect(curve("character:oath_01_aveline", "character_five_star_pity", 80, 4)).toEqual(GOLDEN.curve.character_four);
    expect(curve("character:oath_01_aveline", "character_five_star_pity", 80, 3)).toEqual(GOLDEN.curve.character_three);
  });

  it("invalid banners, targets and pity states fail with the reference's class and message", () => {
    for (const entry of GOLDEN.errors as Any[]) {
      const got = failure(() => rules.pull(pityState(entry.state), entry.banner_id, new CpythonRandom(0n)));
      expect(got, `${entry.banner_id} ${JSON.stringify(entry.state)}`).toEqual(entry.error);
    }
  });

  it("transaction-shaped 1- and 10-pulls (pure part of _resolve_and_persist_pulls)", () => {
    for (const entry of GOLDEN.plans as Any[]) {
      const plan = rules.resolvePulls({
        stored: entry.stored,
        banner_id: entry.banner_id,
        pull_count: entry.pull_count,
        open_banner_ids: OPEN,
        target_id: entry.target_id,
        rng: new CpythonRandom(BigInt(entry.seed)),
      });
      expect(plan.banner_type).toBe(entry.banner_type);
      expect(plan.total_cost).toBe(entry.total_cost);
      expect(plan.results.map((result) => [result.rarity, result.reward_id, result.is_featured])).toEqual(entry.rewards);
      expect(pityStatePayload(plan.final_state)).toEqual(entry.final);
    }
    for (const entry of GOLDEN.plan_errors as Any[]) {
      const got = failure(() =>
        rules.resolvePulls({
          stored: entry.stored,
          banner_id: entry.banner_id,
          pull_count: entry.pull_count,
          open_banner_ids: entry.open,
          target_id: entry.target_id,
          rng: new CpythonRandom(0n),
        }),
      );
      expect(got, entry.banner_id).toEqual(entry.error);
    }
  });

  it("rotation windows and epoch validation", () => {
    for (const entry of GOLDEN.rotation as Any[]) {
      const windows = rules.openBanners(new Date(entry.now), EPOCH);
      expect(windows.map((window) => [window.banner_id, window.closes_at ? isoUtc(window.closes_at) : null]), entry.now).toEqual(
        entry.windows,
      );
    }
    for (const [text, error] of GOLDEN.epoch_errors as [string, unknown][]) {
      expect(failure(() => parseEpoch(text)), text).toEqual(error);
    }
  });
});

